                                    try
                                    {
                                        var message = email.PrepareMessage(item.SenderName + "<" + item.SenderEmail + ">", toList, ccList, bccList, item.Subject, item.MessageBody);
                                        message.Attachments.Add(new Attachment(path.ToString()));
