                                sheet1.Range[xlsRow, colWeekOffHoliday].Number = clsStaticInfo.dbl(subTotalCatgWeekOff.ToString());//"=SUM(" + ru.GetColumnNameForXls(colWeekOffHoliday) + catFRow + ":" + ru.GetColumnNameForXls(colWeekOffHoliday) + (xlsRow - 1) + ")";


