                                var path = filePath;// _attendanceManagementService.GetIndividualDailyOT("",item.CompanyGroupId, item.PlantId,"","",DateTime.Now.ToString("dd-MMM-yyyy"),DateTime.Now.ToString(),"0","");


                                if (!string.IsNullOrEmpty(path.ToString()))
